package com.neueda.controller;

import com.neueda.dto.ErrorResponse;
import com.neueda.exception.DuplicatePaymentException;
import com.neueda.exception.InvalidStatusTransitionException;
import com.neueda.exception.PaymentNotFoundException;
import com.neueda.exception.ValidationException;
import com.neueda.model.ErrorCode;
import com.neueda.model.PaymentStatus;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class GlobalExceptionHandlerTest {

    private final GlobalExceptionHandler handler = new GlobalExceptionHandler();

    @Test
    void handleValidationExceptionReturnsStructuredBadRequest() {
        ResponseEntity<ErrorResponse> response = handler.handleValidationException(
            new ValidationException(ErrorCode.INVALID_CURRENCY, "Currency must be supported")
        );

        assertAll(
            () -> assertEquals(400, response.getStatusCode().value()),
            () -> assertEquals("INVALID_CURRENCY", response.getBody().getErrorCode()),
            () -> assertEquals("Currency must be supported", response.getBody().getDetails()),
            () -> assertNotNull(response.getBody().getTimestamp())
        );
    }

    @Test
    void handlePaymentNotFoundExceptionReturnsNotFound() {
        ResponseEntity<ErrorResponse> response = handler.handlePaymentNotFoundException(new PaymentNotFoundException(88L));

        assertAll(
            () -> assertEquals(HttpStatus.NOT_FOUND, response.getStatusCode()),
            () -> assertEquals("PAYMENT_NOT_FOUND", response.getBody().getErrorCode()),
            () -> assertEquals("Payment ID 88 does not exist", response.getBody().getDetails())
        );
    }

    @Test
    void handleInvalidStatusTransitionExceptionReturnsBadRequest() {
        ResponseEntity<ErrorResponse> response = handler.handleInvalidStatusTransitionException(
            new InvalidStatusTransitionException(PaymentStatus.CREATED, PaymentStatus.COMPLETED)
        );

        assertAll(
            () -> assertEquals(HttpStatus.BAD_REQUEST, response.getStatusCode()),
            () -> assertEquals("INVALID_STATUS_TRANSITION", response.getBody().getErrorCode()),
            () -> assertEquals("Cannot transition from CREATED to COMPLETED", response.getBody().getDetails())
        );
    }

    @Test
    void handleDuplicatePaymentExceptionReturnsConflict() {
        ResponseEntity<ErrorResponse> response = handler.handleDuplicatePaymentException(
            new DuplicatePaymentException("idem-88", 88L)
        );

        assertAll(
            () -> assertEquals(HttpStatus.CONFLICT, response.getStatusCode()),
            () -> assertEquals("DUPLICATE_PAYMENT", response.getBody().getErrorCode()),
            () -> assertEquals("Idempotency key 'idem-88' already exists with Payment ID 88", response.getBody().getDetails())
        );
    }

    @Test
    void handleGenericExceptionReturnsProcessingError() {
        ResponseEntity<ErrorResponse> response = handler.handleGenericException(new RuntimeException("unexpected failure"));

        assertAll(
            () -> assertEquals(HttpStatus.INTERNAL_SERVER_ERROR, response.getStatusCode()),
            () -> assertEquals("PROCESSING_ERROR", response.getBody().getErrorCode()),
            () -> assertEquals("unexpected failure", response.getBody().getDetails())
        );
    }
}

package com.neueda.controller;

import com.neueda.model.Payment;
import com.neueda.service.PaymentService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

class PaymentControllerTest {

    private MockMvc mockMvc;

    @BeforeEach
    void setUp() {
        PaymentService paymentService = new PaymentService() {
            @Override
            public Payment createPayment(Payment payment) {
                payment.setId(99L);
                if (payment.getStatus() == null) {
                    payment.setStatus("CREATED");
                }
                return payment;
            }

            @Override
            public Optional<Payment> getPaymentById(Long id) {
                if (id.equals(99L)) {
                    return Optional.of(new Payment(
                            99L,
                            new BigDecimal("125.50"),
                            "CREATED",
                            "ACC001",
                            "ACC002",
                            "idem-001"
                    ));
                }
                return Optional.empty();
            }

            @Override
            public List<Payment> getAllPayments() {
                return List.of();
            }

            @Override
            public Optional<Payment> getPaymentByIdempotencyKey(String key) {
                return Optional.empty();
            }
        };

        mockMvc = MockMvcBuilders.standaloneSetup(new PaymentController(paymentService)).build();
    }

    @Test
    void createPaymentReturnsCreatedPayment() throws Exception {
        String paymentJson = """
                {
                  "amount": 125.50,
                  "sourceAccount": "ACC001",
                  "destinationAccount": "ACC002",
                  "idempotencyKey": "idem-001"
                }
                """;

        mockMvc.perform(post("/payments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(paymentJson))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.id").value(99))
                .andExpect(jsonPath("$.status").value("CREATED"))
                .andExpect(jsonPath("$.sourceAccount").value("ACC001"))
                .andExpect(jsonPath("$.destinationAccount").value("ACC002"))
                .andExpect(jsonPath("$.idempotencyKey").value("idem-001"));
    }

    @Test
    void getPaymentByIdReturnsPaymentWhenPresent() throws Exception {
        mockMvc.perform(get("/payments/99"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(99))
                .andExpect(jsonPath("$.status").value("CREATED"))
                .andExpect(jsonPath("$.sourceAccount").value("ACC001"))
                .andExpect(jsonPath("$.destinationAccount").value("ACC002"));
    }

    @Test
    void getPaymentByIdReturnsNotFoundWhenMissing() throws Exception {
        mockMvc.perform(get("/payments/1000"))
                .andExpect(status().isNotFound());
    }
}

package com.neueda.controller;

import com.neueda.exception.DuplicatePaymentException;
import com.neueda.exception.ValidationException;
import com.neueda.model.ErrorCode;
import com.neueda.model.Payment;
import com.neueda.service.PaymentService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

class PaymentControllerTest {

    private MockMvc mockMvc;
    private StubPaymentService paymentService;

    @BeforeEach
    void setUp() {
        paymentService = new StubPaymentService();
        mockMvc = MockMvcBuilders.standaloneSetup(new PaymentController(paymentService))
            .setControllerAdvice(new GlobalExceptionHandler())
            .build();
    }

    @Test
    void createPaymentReturnsCreatedPayment() throws Exception {
        paymentService.createdPayment = payment(99L, "CREATED", "idem-001");

        mockMvc.perform(post("/payments")
                .contentType(MediaType.APPLICATION_JSON)
                .content(validPaymentJson("idem-001")))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.id").value(99))
            .andExpect(jsonPath("$.status").value("CREATED"))
            .andExpect(jsonPath("$.sourceAccount").value("ACC00111"))
            .andExpect(jsonPath("$.destinationAccount").value("ACC00222"))
            .andExpect(jsonPath("$.idempotencyKey").value("idem-001"));
    }

    @Test
    void getPaymentByIdReturnsPaymentWhenPresent() throws Exception {
        paymentService.paymentById = Optional.of(payment(99L, "CREATED", "idem-001"));

        mockMvc.perform(get("/payments/99"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(99))
            .andExpect(jsonPath("$.status").value("CREATED"))
            .andExpect(jsonPath("$.sourceAccount").value("ACC00111"))
            .andExpect(jsonPath("$.destinationAccount").value("ACC00222"));
    }

    @Test
    void getPaymentByIdReturnsNotFoundWhenMissing() throws Exception {
        paymentService.paymentById = Optional.empty();

        mockMvc.perform(get("/payments/1000"))
            .andExpect(status().isNotFound());
    }

    @Test
    void createPaymentReturnsValidationErrorWhenServiceRejectsRequest() throws Exception {
        paymentService.createException = new ValidationException(ErrorCode.INVALID_AMOUNT, "Amount must be greater than 0");

        mockMvc.perform(post("/payments")
                .contentType(MediaType.APPLICATION_JSON)
                .content(validPaymentJson("idem-invalid")))
            .andExpect(status().isBadRequest())
            .andExpect(jsonPath("$.errorCode").value("INVALID_AMOUNT"))
            .andExpect(jsonPath("$.httpStatus").value(400))
            .andExpect(jsonPath("$.details").value("Amount must be greater than 0"));
    }

    @Test
    void createPaymentReturnsConflictWhenDuplicatePaymentDetected() throws Exception {
        paymentService.createException = new DuplicatePaymentException("idem-duplicate", 101L);

        mockMvc.perform(post("/payments")
                .contentType(MediaType.APPLICATION_JSON)
                .content(validPaymentJson("idem-duplicate")))
            .andExpect(status().isConflict())
            .andExpect(jsonPath("$.errorCode").value("DUPLICATE_PAYMENT"))
            .andExpect(jsonPath("$.httpStatus").value(409))
            .andExpect(jsonPath("$.details").value("Idempotency key 'idem-duplicate' already exists with Payment ID 101"));
    }

    @Test
    void createPaymentReturnsBadRequestForMalformedJson() throws Exception {
        mockMvc.perform(post("/payments")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"amount\": }"))
            .andExpect(status().isBadRequest());
    }

    @Test
    void getPaymentByIdReturnsInternalServerErrorForUnexpectedException() throws Exception {
        paymentService.readException = new RuntimeException("database unavailable");

        mockMvc.perform(get("/payments/55"))
            .andExpect(status().isInternalServerError())
            .andExpect(jsonPath("$.errorCode").value("PROCESSING_ERROR"))
            .andExpect(jsonPath("$.httpStatus").value(500))
            .andExpect(jsonPath("$.details").value("database unavailable"));
    }

    private static Payment payment(Long id, String status, String key) {
        return new Payment(id, new BigDecimal("125.50"), status, "ACC00111", "ACC00222", key);
    }

    private static String validPaymentJson(String key) {
        return """
            {
              "amount": 125.50,
              "status": "CREATED",
              "sourceAccount": "ACC00111",
              "destinationAccount": "ACC00222",
              "idempotencyKey": "%s"
            }
            """.formatted(key);
    }

    private static class StubPaymentService implements PaymentService {
        private Payment createdPayment;
        private Optional<Payment> paymentById = Optional.empty();
        private RuntimeException createException;
        private RuntimeException readException;

        @Override
        public Payment createPayment(Payment payment) {
            if (createException != null) {
                throw createException;
            }
            return createdPayment;
        }

        @Override
        public Optional<Payment> getPaymentById(Long id) {
            if (readException != null) {
                throw readException;
            }
            return paymentById;
        }

        @Override
        public List<Payment> getAllPayments() {
            return List.of();
        }

        @Override
        public Optional<Payment> getPaymentByIdempotencyKey(String key) {
            return Optional.empty();
        }
    }
}

package com.neueda.dto;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class CreatePaymentRequestTest {

    @Test
    void constructorPopulatesCoreFields() {
        CreatePaymentRequest request = new CreatePaymentRequest(
            new BigDecimal("150.75"),
            "USD",
            "SOURCE123",
            "TARGET123",
            "idem-123"
        );

        assertAll(
            () -> assertEquals(new BigDecimal("150.75"), request.getAmount()),
            () -> assertEquals("USD", request.getCurrency()),
            () -> assertEquals("SOURCE123", request.getSourceAccount()),
            () -> assertEquals("TARGET123", request.getDestinationAccount()),
            () -> assertEquals("idem-123", request.getIdempotencyKey()),
            () -> assertNull(request.getReference())
        );
    }

    @Test
    void settersUpdateAllFields() {
        CreatePaymentRequest request = new CreatePaymentRequest();

        request.setAmount(new BigDecimal("10.00"));
        request.setCurrency("EUR");
        request.setSourceAccount("ACC11111");
        request.setDestinationAccount("ACC22222");
        request.setIdempotencyKey("idem-456");
        request.setReference("invoice-2026-08");

        assertAll(
            () -> assertEquals(new BigDecimal("10.00"), request.getAmount()),
            () -> assertEquals("EUR", request.getCurrency()),
            () -> assertEquals("ACC11111", request.getSourceAccount()),
            () -> assertEquals("ACC22222", request.getDestinationAccount()),
            () -> assertEquals("idem-456", request.getIdempotencyKey()),
            () -> assertEquals("invoice-2026-08", request.getReference())
        );
    }
}

package com.neueda.dto;

import com.neueda.model.ErrorCode;
import org.junit.jupiter.api.Test;

import java.time.LocalDateTime;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class ErrorResponseTest {

    @Test
    void enumBasedConstructorMapsErrorMetadata() {
        ErrorResponse response = new ErrorResponse(ErrorCode.INVALID_AMOUNT, "Amount cannot be zero");

        assertAll(
            () -> assertEquals("INVALID_AMOUNT", response.getErrorCode()),
            () -> assertEquals(ErrorCode.INVALID_AMOUNT.getMessage(), response.getMessage()),
            () -> assertEquals(400, response.getHttpStatus()),
            () -> assertEquals("Amount cannot be zero", response.getDetails()),
            () -> assertNotNull(response.getTimestamp())
        );
    }

    @Test
    void explicitConstructorAndSettersAllowCustomisation() {
        ErrorResponse response = new ErrorResponse("CUSTOM", "Custom message", 418, "Teapot details");
        LocalDateTime timestamp = LocalDateTime.of(2026, 8, 4, 16, 45);

        response.setErrorCode("UPDATED");
        response.setMessage("Updated message");
        response.setHttpStatus(422);
        response.setDetails("Updated details");
        response.setTimestamp(timestamp);

        assertAll(
            () -> assertEquals("UPDATED", response.getErrorCode()),
            () -> assertEquals("Updated message", response.getMessage()),
            () -> assertEquals(422, response.getHttpStatus()),
            () -> assertEquals("Updated details", response.getDetails()),
            () -> assertEquals(timestamp, response.getTimestamp())
        );
    }
}

package com.neueda.exception;

import com.neueda.model.ErrorCode;
import com.neueda.model.PaymentStatus;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PaymentExceptionsTest {

    @Test
    void validationExceptionWithErrorCodeRetainsMetadata() {
        ValidationException exception = new ValidationException(ErrorCode.INVALID_AMOUNT, "Amount must be positive");

        assertAll(
            () -> assertEquals(ErrorCode.INVALID_AMOUNT, exception.getErrorCode()),
            () -> assertEquals("Amount must be positive", exception.getDetails()),
            () -> assertTrue(exception.getMessage().contains(ErrorCode.INVALID_AMOUNT.getMessage()))
        );
    }

    @Test
    void validationExceptionWithMessageDefaultsToValidationFailed() {
        ValidationException exception = new ValidationException("Generic validation failure");

        assertAll(
            () -> assertEquals(ErrorCode.VALIDATION_FAILED, exception.getErrorCode()),
            () -> assertEquals("Generic validation failure", exception.getDetails()),
            () -> assertEquals("Generic validation failure", exception.getMessage())
        );
    }

    @Test
    void duplicatePaymentExceptionExposesConflictingIdentifiers() {
        DuplicatePaymentException exception = new DuplicatePaymentException("idem-dup", 42L);

        assertAll(
            () -> assertEquals(ErrorCode.DUPLICATE_PAYMENT, exception.getErrorCode()),
            () -> assertEquals("idem-dup", exception.getIdempotencyKey()),
            () -> assertEquals(42L, exception.getExistingPaymentId()),
            () -> assertTrue(exception.getMessage().contains("idem-dup"))
        );
    }

    @Test
    void invalidStatusTransitionExceptionExposesFromAndToStatus() {
        InvalidStatusTransitionException exception = new InvalidStatusTransitionException(PaymentStatus.CREATED, PaymentStatus.COMPLETED);

        assertAll(
            () -> assertEquals(ErrorCode.INVALID_STATUS_TRANSITION, exception.getErrorCode()),
            () -> assertEquals(PaymentStatus.CREATED, exception.getFromStatus()),
            () -> assertEquals(PaymentStatus.COMPLETED, exception.getToStatus()),
            () -> assertTrue(exception.getMessage().contains("CREATED")),
            () -> assertTrue(exception.getMessage().contains("COMPLETED"))
        );
    }

    @Test
    void paymentNotFoundExceptionExposesPaymentId() {
        PaymentNotFoundException exception = new PaymentNotFoundException(77L);

        assertAll(
            () -> assertEquals(ErrorCode.PAYMENT_NOT_FOUND, exception.getErrorCode()),
            () -> assertEquals(77L, exception.getPaymentId()),
            () -> assertTrue(exception.getMessage().contains("77"))
        );
    }
}

package com.neueda.model;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;

class AccountTest {

    @Test
    void fullConstructorPopulatesAllFields() {
        Account account = new Account(1L, "ACC12345", "Alice", "USD", new BigDecimal("100.50"), "ACTIVE");

        assertAll(
            () -> assertEquals(1L, account.getId()),
            () -> assertEquals("ACC12345", account.getAccountNumber()),
            () -> assertEquals("Alice", account.getAccountHolderName()),
            () -> assertEquals("USD", account.getAccountCurrencyType()),
            () -> assertEquals(new BigDecimal("100.50"), account.getBalance()),
            () -> assertEquals("ACTIVE", account.getStatus())
        );
    }

    @Test
    void settersUpdateEachField() {
        Account account = new Account();

        account.setId(7L);
        account.setAccountNumber("ACC76543");
        account.setAccountHolderName("Bob");
        account.setAccountCurrencyType("EUR");
        account.setBalance(new BigDecimal("999.99"));
        account.setStatus("BLOCKED");

        assertAll(
            () -> assertEquals(7L, account.getId()),
            () -> assertEquals("ACC76543", account.getAccountNumber()),
            () -> assertEquals("Bob", account.getAccountHolderName()),
            () -> assertEquals("EUR", account.getAccountCurrencyType()),
            () -> assertEquals(new BigDecimal("999.99"), account.getBalance()),
            () -> assertEquals("BLOCKED", account.getStatus())
        );
    }
}

package com.neueda.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

class ErrorCodeTest {

    @Test
    void eachErrorCodeExposesExpectedHttpStatusAndMessage() {
        assertAll(
            () -> assertEquals(400, ErrorCode.VALIDATION_FAILED.getHttpStatus()),
            () -> assertEquals(400, ErrorCode.INSUFFICIENT_FUNDS.getHttpStatus()),
            () -> assertEquals(400, ErrorCode.INVALID_ACCOUNT.getHttpStatus()),
            () -> assertEquals(400, ErrorCode.INVALID_CURRENCY.getHttpStatus()),
            () -> assertEquals(400, ErrorCode.INVALID_AMOUNT.getHttpStatus()),
            () -> assertEquals(409, ErrorCode.DUPLICATE_PAYMENT.getHttpStatus()),
            () -> assertEquals(400, ErrorCode.INVALID_STATUS_TRANSITION.getHttpStatus()),
            () -> assertEquals(404, ErrorCode.PAYMENT_NOT_FOUND.getHttpStatus()),
            () -> assertEquals(500, ErrorCode.PROCESSING_ERROR.getHttpStatus()),
            () -> assertEquals(503, ErrorCode.NETWORK_ERROR.getHttpStatus())
        );

        for (ErrorCode errorCode : ErrorCode.values()) {
            assertFalse(errorCode.getMessage().isBlank(), () -> errorCode + " should have a message");
        }
    }
}

package com.neueda.model;

import org.junit.jupiter.api.Test;

import java.time.LocalDateTime;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class PaymentHistoryTest {

    @Test
    void fullConstructorPopulatesAllFields() {
        LocalDateTime timestamp = LocalDateTime.of(2026, 8, 4, 12, 0);

        PaymentHistory history = new PaymentHistory(1L, 99L, "CREATED", "VALIDATED", timestamp, "Validation succeeded");

        assertAll(
            () -> assertEquals(1L, history.getId()),
            () -> assertEquals(99L, history.getPaymentId()),
            () -> assertEquals("CREATED", history.getFromStatus()),
            () -> assertEquals("VALIDATED", history.getToStatus()),
            () -> assertEquals(timestamp, history.getTimestamp()),
            () -> assertEquals("Validation succeeded", history.getNotes())
        );
    }

    @Test
    void insertConstructorLeavesIdUnset() {
        LocalDateTime timestamp = LocalDateTime.of(2026, 8, 4, 13, 30);

        PaymentHistory history = new PaymentHistory(100L, "VALIDATED", "SENT", timestamp, null);

        assertAll(
            () -> assertNull(history.getId()),
            () -> assertEquals(100L, history.getPaymentId()),
            () -> assertEquals("VALIDATED", history.getFromStatus()),
            () -> assertEquals("SENT", history.getToStatus()),
            () -> assertEquals(timestamp, history.getTimestamp()),
            () -> assertNull(history.getNotes())
        );
    }

    @Test
    void settersUpdateEachField() {
        LocalDateTime timestamp = LocalDateTime.now();
        PaymentHistory history = new PaymentHistory();

        history.setId(5L);
        history.setPaymentId(12L);
        history.setFromStatus("SENT");
        history.setToStatus("COMPLETED");
        history.setTimestamp(timestamp);
        history.setNotes("Network confirmation received");

        assertAll(
            () -> assertEquals(5L, history.getId()),
            () -> assertEquals(12L, history.getPaymentId()),
            () -> assertEquals("SENT", history.getFromStatus()),
            () -> assertEquals("COMPLETED", history.getToStatus()),
            () -> assertEquals(timestamp, history.getTimestamp()),
            () -> assertEquals("Network confirmation received", history.getNotes())
        );
    }
}

package com.neueda.model;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PaymentStatusTest {

    @Test
    void descriptionsArePresentForAllStatuses() {
        for (PaymentStatus status : PaymentStatus.values()) {
            assertFalse(status.getDescription().isBlank(), () -> status + " should have a description");
        }
    }

    @Test
    void validLifecycleTransitionsAreAllowed() {
        assertAll(
            () -> assertTrue(PaymentStatus.CREATED.canTransitionTo(PaymentStatus.VALIDATED)),
            () -> assertTrue(PaymentStatus.CREATED.canTransitionTo(PaymentStatus.FAILED)),
            () -> assertTrue(PaymentStatus.VALIDATED.canTransitionTo(PaymentStatus.SENT)),
            () -> assertTrue(PaymentStatus.VALIDATED.canTransitionTo(PaymentStatus.FAILED)),
            () -> assertTrue(PaymentStatus.SENT.canTransitionTo(PaymentStatus.COMPLETED)),
            () -> assertTrue(PaymentStatus.SENT.canTransitionTo(PaymentStatus.FAILED))
        );
    }

    @Test
    void invalidLifecycleTransitionsAreRejected() {
        assertAll(
            () -> assertFalse(PaymentStatus.CREATED.canTransitionTo(PaymentStatus.CREATED)),
            () -> assertFalse(PaymentStatus.CREATED.canTransitionTo(PaymentStatus.SENT)),
            () -> assertFalse(PaymentStatus.CREATED.canTransitionTo(PaymentStatus.COMPLETED)),
            () -> assertFalse(PaymentStatus.VALIDATED.canTransitionTo(PaymentStatus.CREATED)),
            () -> assertFalse(PaymentStatus.VALIDATED.canTransitionTo(PaymentStatus.COMPLETED)),
            () -> assertFalse(PaymentStatus.SENT.canTransitionTo(PaymentStatus.CREATED)),
            () -> assertFalse(PaymentStatus.SENT.canTransitionTo(PaymentStatus.VALIDATED)),
            () -> assertFalse(PaymentStatus.COMPLETED.canTransitionTo(PaymentStatus.FAILED)),
            () -> assertFalse(PaymentStatus.COMPLETED.canTransitionTo(PaymentStatus.COMPLETED)),
            () -> assertFalse(PaymentStatus.FAILED.canTransitionTo(PaymentStatus.CREATED)),
            () -> assertFalse(PaymentStatus.FAILED.canTransitionTo(PaymentStatus.FAILED))
        );
    }
}

package com.neueda.model;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

class PaymentTest {

    @Test
    void partialConstructorLeavesAuditFieldsUnset() {
        Payment payment = new Payment(10L, new BigDecimal("125.50"), "CREATED", "SRC12345", "DST12345", "idem-10");

        assertAll(
            () -> assertEquals(10L, payment.getId()),
            () -> assertEquals(new BigDecimal("125.50"), payment.getAmount()),
            () -> assertEquals("CREATED", payment.getStatus()),
            () -> assertEquals("SRC12345", payment.getSourceAccount()),
            () -> assertEquals("DST12345", payment.getDestinationAccount()),
            () -> assertEquals("idem-10", payment.getIdempotencyKey()),
            () -> assertNull(payment.getCreatedAt()),
            () -> assertNull(payment.getUpdatedAt()),
            () -> assertNull(payment.getCurrency()),
            () -> assertNull(payment.getErrorCode())
        );
    }

    @Test
    void extendedConstructorPopulatesAuditFields() {
        LocalDateTime createdAt = LocalDateTime.of(2026, 8, 4, 10, 15);
        LocalDateTime updatedAt = createdAt.plusMinutes(5);

        Payment payment = new Payment(
            20L,
            new BigDecimal("300.00"),
            "FAILED",
            "SRC67890",
            "DST67890",
            "idem-20",
            createdAt,
            updatedAt,
            "USD",
            ErrorCode.PROCESSING_ERROR.name()
        );

        assertAll(
            () -> assertEquals(20L, payment.getId()),
            () -> assertEquals(createdAt, payment.getCreatedAt()),
            () -> assertEquals(updatedAt, payment.getUpdatedAt()),
            () -> assertEquals("USD", payment.getCurrency()),
            () -> assertEquals(ErrorCode.PROCESSING_ERROR.name(), payment.getErrorCode())
        );
    }

    @Test
    void settersUpdateEachField() {
        LocalDateTime now = LocalDateTime.now();
        Payment payment = new Payment();

        payment.setId(30L);
        payment.setAmount(new BigDecimal("10.25"));
        payment.setStatus("VALIDATED");
        payment.setSourceAccount("SOURCE111");
        payment.setDestinationAccount("TARGET222");
        payment.setIdempotencyKey("idem-30");
        payment.setCreatedAt(now);
        payment.setUpdatedAt(now.plusSeconds(30));
        payment.setCurrency("EUR");
        payment.setErrorCode(ErrorCode.INVALID_ACCOUNT.name());

        assertAll(
            () -> assertEquals(30L, payment.getId()),
            () -> assertEquals(new BigDecimal("10.25"), payment.getAmount()),
            () -> assertEquals("VALIDATED", payment.getStatus()),
            () -> assertEquals("SOURCE111", payment.getSourceAccount()),
            () -> assertEquals("TARGET222", payment.getDestinationAccount()),
            () -> assertEquals("idem-30", payment.getIdempotencyKey()),
            () -> assertEquals(now, payment.getCreatedAt()),
            () -> assertEquals(now.plusSeconds(30), payment.getUpdatedAt()),
            () -> assertEquals("EUR", payment.getCurrency()),
            () -> assertEquals(ErrorCode.INVALID_ACCOUNT.name(), payment.getErrorCode())
        );
    }
}

package com.neueda.repository;



import com.neueda.model.Account;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.jdbc.test.autoconfigure.JdbcTest;
import org.springframework.context.annotation.Import;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

@JdbcTest
@Import(AccountRepositoryImplementation.class)
class AccountRepositoryTests {

    @Autowired
    private AccountRepositoryImplementation repository;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @BeforeEach
    void cleanTables() {
        jdbcTemplate.update("DELETE FROM payment_history");
        jdbcTemplate.update("DELETE FROM payments");
        jdbcTemplate.update("DELETE FROM accounts");
    }

    @Test
    void savePersistsAccountAndGeneratesId() {
        Account account = account(null, "ACC10001", "Alice", "USD", "1500.25", "ACTIVE");

        Account saved = repository.save(account);

        assertNotNull(saved.getId());
        Optional<Account> reloaded = repository.findById(saved.getId());
        assertTrue(reloaded.isPresent());
        assertAll(
            () -> assertEquals("ACC10001", reloaded.get().getAccountNumber()),
            () -> assertEquals("Alice", reloaded.get().getAccountHolderName()),
            () -> assertEquals("USD", reloaded.get().getAccountCurrencyType()),
            () -> assertEquals(new BigDecimal("1500.25"), reloaded.get().getBalance()),
            () -> assertEquals("ACTIVE", reloaded.get().getStatus())
        );
    }

    @Test
    void findByIdReturnsEmptyWhenAccountDoesNotExist() {
        assertFalse(repository.findById(9999L).isPresent());
    }

    @Test
    void findByAccountNumberReturnsMatchingAccount() {
        Account saved = repository.save(account(null, "ACC20002", "Bob", "EUR", "250.00", "ACTIVE"));

        Optional<Account> result = repository.findByAccountNumber("ACC20002");

        assertTrue(result.isPresent());
        assertEquals(saved.getId(), result.get().getId());
    }

    @Test
    void findAllReturnsAllPersistedAccounts() {
        repository.save(account(null, "ACC30003", "Carol", "GBP", "75.00", "ACTIVE"));
        repository.save(account(null, "ACC40004", "Dave", "USD", "95.00", "BLOCKED"));

        List<Account> accounts = repository.findAll();

        assertEquals(2, accounts.size());
    }

    @Test
    void saveRejectsDuplicateAccountNumber() {
        repository.save(account(null, "ACC50005", "Eve", "USD", "600.00", "ACTIVE"));

        assertThrows(DataAccessException.class,
            () -> repository.save(account(null, "ACC50005", "Frank", "USD", "700.00", "ACTIVE")));
    }

    private static Account account(Long id, String number, String holder, String currency, String balance, String status) {
        return new Account(id, number, holder, currency, new BigDecimal(balance), status);
    }
}

package com.neueda.repository;

import com.neueda.model.PaymentHistory;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.jdbc.test.autoconfigure.JdbcTest;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

@JdbcTest
@Import(PaymentHistoryRepositoryImplementation.class)
class PaymentHistoryRepositoryImplementationTest {

    @Autowired
    private PaymentHistoryRepositoryImplementation repository;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @BeforeEach
    void cleanTables() {
        jdbcTemplate.update("DELETE FROM payment_history");
        jdbcTemplate.update("DELETE FROM payments");
        jdbcTemplate.update("DELETE FROM accounts");
    }

    @Test
    void savePersistsHistoryEntryAndGeneratesId() {
        Long paymentId = insertPayment("idem-history-1");
        LocalDateTime timestamp = LocalDateTime.of(2026, 8, 4, 18, 0);
        PaymentHistory history = new PaymentHistory(paymentId, "CREATED", "VALIDATED", timestamp, "Validation passed");

        PaymentHistory saved = repository.save(history);

        assertNotNull(saved.getId());
        List<PaymentHistory> historyEntries = repository.findByPaymentId(paymentId);
        assertEquals(1, historyEntries.size());
        assertAll(
            () -> assertEquals("CREATED", historyEntries.getFirst().getFromStatus()),
            () -> assertEquals("VALIDATED", historyEntries.getFirst().getToStatus()),
            () -> assertEquals(timestamp, historyEntries.getFirst().getTimestamp()),
            () -> assertEquals("Validation passed", historyEntries.getFirst().getNotes())
        );
    }

    @Test
    void saveUsesCurrentTimestampWhenTimestampIsNotProvided() {
        Long paymentId = insertPayment("idem-history-2");

        repository.save(new PaymentHistory(paymentId, "VALIDATED", "SENT", null, "Queued for dispatch"));

        PaymentHistory reloaded = repository.findByPaymentId(paymentId).getFirst();
        assertNotNull(reloaded.getTimestamp());
        assertEquals("Queued for dispatch", reloaded.getNotes());
    }

    @Test
    void findByPaymentIdReturnsEntriesInReverseChronologicalOrder() {
        Long paymentId = insertPayment("idem-history-3");
        repository.save(new PaymentHistory(paymentId, "CREATED", "VALIDATED", LocalDateTime.of(2026, 8, 4, 10, 0), "validated"));
        repository.save(new PaymentHistory(paymentId, "VALIDATED", "SENT", LocalDateTime.of(2026, 8, 4, 11, 0), "sent"));
        repository.save(new PaymentHistory(paymentId, "SENT", "COMPLETED", LocalDateTime.of(2026, 8, 4, 12, 0), "completed"));

        List<PaymentHistory> historyEntries = repository.findByPaymentId(paymentId);

        assertEquals(3, historyEntries.size());
        assertAll(
            () -> assertEquals("COMPLETED", historyEntries.get(0).getToStatus()),
            () -> assertEquals("SENT", historyEntries.get(1).getToStatus()),
            () -> assertEquals("VALIDATED", historyEntries.get(2).getToStatus())
        );
    }

    @Test
    void findByPaymentIdReturnsEmptyListWhenNoEntriesExist() {
        assertTrue(repository.findByPaymentId(9999L).isEmpty());
    }

    private Long insertPayment(String idempotencyKey) {
        jdbcTemplate.update(
            """
            INSERT INTO payments (amount, status, source_account, destination_account, idempotency_key, currency, created_at, updated_at, error_code)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            new BigDecimal("55.00"),
            "CREATED",
            "ACC03030",
            "ACC04040",
            idempotencyKey,
            "USD",
            Timestamp.valueOf(LocalDateTime.of(2026, 8, 4, 9, 0)),
            Timestamp.valueOf(LocalDateTime.of(2026, 8, 4, 9, 0)),
            null
        );
        return jdbcTemplate.queryForObject("SELECT id FROM payments WHERE idempotency_key = ?", Long.class, idempotencyKey);
    }
}

package com.neueda.repository;

import com.neueda.model.Payment;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.jdbc.test.autoconfigure.JdbcTest;
import org.springframework.context.annotation.Import;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

@JdbcTest
@Import(PaymentRepositoryImplementation.class)
class PaymentRepositoryImplementationTest {

    @Autowired
    private PaymentRepositoryImplementation repository;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @BeforeEach
    void cleanTables() {
        jdbcTemplate.update("DELETE FROM payment_history");
        jdbcTemplate.update("DELETE FROM payments");
        jdbcTemplate.update("DELETE FROM accounts");
    }

    @Test
    void savePersistsPaymentAndAuditColumns() {
        Payment payment = payment(null, "CREATED", "idem-save", "100.25", "USD", null);

        Payment saved = repository.save(payment);

        assertNotNull(saved.getId());
        Payment reloaded = repository.findById(saved.getId()).orElseThrow();
        assertAll(
            () -> assertEquals(new BigDecimal("100.25"), reloaded.getAmount()),
            () -> assertEquals("CREATED", reloaded.getStatus()),
            () -> assertEquals("ACC01010", reloaded.getSourceAccount()),
            () -> assertEquals("ACC02020", reloaded.getDestinationAccount()),
            () -> assertEquals("idem-save", reloaded.getIdempotencyKey()),
            () -> assertEquals("USD", reloaded.getCurrency()),
            () -> assertNotNull(reloaded.getCreatedAt()),
            () -> assertNotNull(reloaded.getUpdatedAt())
        );
    }

    @Test
    void findByIdReturnsEmptyWhenPaymentIsMissing() {
        assertFalse(repository.findById(123456L).isPresent());
    }

    @Test
    void findByIdempotencyKeyReturnsMatchingPayment() {
        Payment saved = repository.save(payment(null, "VALIDATED", "idem-find-key", "75.00", "EUR", null));

        Optional<Payment> result = repository.findByIdempotencyKey("idem-find-key");

        assertTrue(result.isPresent());
        assertEquals(saved.getId(), result.get().getId());
    }

    @Test
    void findAllByStatusFiltersCorrectly() {
        repository.save(payment(null, "CREATED", "idem-created-1", "10.00", "USD", null));
        repository.save(payment(null, "CREATED", "idem-created-2", "20.00", "USD", null));
        repository.save(payment(null, "FAILED", "idem-failed-1", "30.00", "USD", "PROCESSING_ERROR"));

        List<Payment> createdPayments = repository.findAllByStatus("CREATED");
        List<Payment> failedPayments = repository.findAllByStatus("FAILED");

        assertAll(
            () -> assertEquals(2, createdPayments.size()),
            () -> assertEquals(1, failedPayments.size()),
            () -> assertEquals("PROCESSING_ERROR", failedPayments.getFirst().getErrorCode())
        );
    }

    @Test
    void updateStatusChangesStatusAndRefreshesUpdatedTimestamp() {
        LocalDateTime originalUpdatedAt = LocalDateTime.of(2025, 1, 1, 10, 0);
        jdbcTemplate.update(
            """
            INSERT INTO payments (amount, status, source_account, destination_account, idempotency_key, currency, created_at, updated_at, error_code)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            new BigDecimal("44.00"),
            "CREATED",
            "ACC01010",
            "ACC02020",
            "idem-update-status",
            "USD",
            Timestamp.valueOf(originalUpdatedAt.minusMinutes(5)),
            Timestamp.valueOf(originalUpdatedAt),
            null
        );
        Long id = jdbcTemplate.queryForObject("SELECT id FROM payments WHERE idempotency_key = ?", Long.class, "idem-update-status");

        repository.updateStatus(id, "VALIDATED");

        Payment updated = repository.findById(id).orElseThrow();
        assertAll(
            () -> assertEquals("VALIDATED", updated.getStatus()),
            () -> assertNotEquals(originalUpdatedAt, updated.getUpdatedAt()),
            () -> assertTrue(updated.getUpdatedAt().isAfter(originalUpdatedAt))
        );
    }

    @Test
    void updatePaymentChangesMutableBusinessFields() {
        Payment saved = repository.save(payment(null, "CREATED", "idem-update-payment", "90.00", "USD", null));
        LocalDateTime originalUpdatedAt = repository.findById(saved.getId()).orElseThrow().getUpdatedAt();

        saved.setAmount(new BigDecimal("120.50"));
        saved.setStatus("FAILED");
        saved.setSourceAccount("ACC77777");
        saved.setDestinationAccount("ACC88888");
        saved.setCurrency("GBP");
        saved.setErrorCode("NETWORK_ERROR");
        repository.updatePayment(saved);

        Payment reloaded = repository.findById(saved.getId()).orElseThrow();
        assertAll(
            () -> assertEquals(new BigDecimal("120.50"), reloaded.getAmount()),
            () -> assertEquals("FAILED", reloaded.getStatus()),
            () -> assertEquals("ACC77777", reloaded.getSourceAccount()),
            () -> assertEquals("ACC88888", reloaded.getDestinationAccount()),
            () -> assertEquals("GBP", reloaded.getCurrency()),
            () -> assertEquals("NETWORK_ERROR", reloaded.getErrorCode()),
            () -> assertTrue(reloaded.getUpdatedAt().isAfter(originalUpdatedAt) || reloaded.getUpdatedAt().isEqual(originalUpdatedAt))
        );
    }

    @Test
    void saveRejectsDuplicateIdempotencyKey() {
        repository.save(payment(null, "CREATED", "idem-duplicate", "15.00", "USD", null));

        assertThrows(DataAccessException.class,
            () -> repository.save(payment(null, "CREATED", "idem-duplicate", "18.00", "USD", null)));
    }

    private static Payment payment(Long id, String status, String key, String amount, String currency, String errorCode) {
        Payment payment = new Payment(id, new BigDecimal(amount), status, "ACC01010", "ACC02020", key);
        payment.setCurrency(currency);
        payment.setErrorCode(errorCode);
        return payment;
    }
}

package com.neueda.service;

